-- Tabelas novas
CREATE TABLE IF NOT EXISTS "PrestacaoContas" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "candidatoId" TEXT NOT NULL,
    "receitas" REAL NOT NULL DEFAULT 0,
    "receitasFundoEleitoral" REAL NOT NULL DEFAULT 0,
    "despesas" REAL NOT NULL DEFAULT 0,
    "fonte" TEXT,
    CONSTRAINT "PrestacaoContas_candidatoId_fkey" FOREIGN KEY ("candidatoId") REFERENCES "Candidato" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "PrestacaoContas_candidatoId_key" ON "PrestacaoContas"("candidatoId");
CREATE TABLE IF NOT EXISTS "CandidatoBens" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "candidatoId" TEXT NOT NULL,
    "total" REAL NOT NULL DEFAULT 0,
    "quantidade" INTEGER NOT NULL DEFAULT 0,
    CONSTRAINT "CandidatoBens_candidatoId_fkey" FOREIGN KEY ("candidatoId") REFERENCES "Candidato" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "CandidatoBens_candidatoId_key" ON "CandidatoBens"("candidatoId");
CREATE TABLE IF NOT EXISTS "Comparecimento" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "municipioId" TEXT NOT NULL,
    "ano" INTEGER NOT NULL,
    "turno" INTEGER NOT NULL DEFAULT 1,
    "aptos" INTEGER NOT NULL,
    "compareceram" INTEGER NOT NULL,
    CONSTRAINT "Comparecimento_municipioId_fkey" FOREIGN KEY ("municipioId") REFERENCES "Municipio" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "Comparecimento_municipioId_ano_turno_key" ON "Comparecimento"("municipioId", "ano", "turno");

-- Financas de campanha 2026 (receitas/FEFC/despesas), bens declarados
-- e comparecimento por municipio (1o turno). Fontes: prestacao de
-- contas, bem_candidato e totalizacao oficial do TSE. Idempotente.
DELETE FROM "PrestacaoContas" WHERE id LIKE 'pc26-%';
DELETE FROM "CandidatoBens" WHERE id LIKE 'cb26-%';
DELETE FROM "Comparecimento" WHERE ano = 2026 AND turno = 1;

