INSERT INTO "PrestacaoContas" (id, candidatoId, receitas, receitasFundoEleitoral, despesas, fonte)
SELECT 'pc26-' || t.cargo || '-' || t.numero, ca.id, t.rec, t.fefc, t.desp, 'TSE, prestação de contas eleitorais 2026 (dados de 18/10/2026)'
FROM tmp_fin26 t
JOIN (SELECT c.nome cargoNome, ca2.numero numero, MIN(ca2.id) id FROM Candidato ca2
      JOIN Cargo c ON ca2.cargoId = c.id JOIN Eleicao e ON c.eleicaoId = e.id
      WHERE e.ano = 2026 GROUP BY c.nome, ca2.numero) ca
  ON ca.cargoNome = t.cargo AND ca.numero = t.numero
WHERE NOT EXISTS (SELECT 1 FROM "PrestacaoContas" p WHERE p.candidatoId = ca.id);
DROP TABLE tmp_fin26;

CREATE TEMP TABLE tmp_bens26 (cargo TEXT, numero INTEGER, total REAL, qtd INTEGER);
