INSERT INTO "CandidatoBens" (id, candidatoId, total, quantidade)
SELECT 'cb26-' || t.cargo || '-' || t.numero, ca.id, t.total, t.qtd
FROM tmp_bens26 t
JOIN (SELECT c.nome cargoNome, ca2.numero numero, MIN(ca2.id) id FROM Candidato ca2
      JOIN Cargo c ON ca2.cargoId = c.id JOIN Eleicao e ON c.eleicaoId = e.id
      WHERE e.ano = 2026 GROUP BY c.nome, ca2.numero) ca
  ON ca.cargoNome = t.cargo AND ca.numero = t.numero
WHERE NOT EXISTS (SELECT 1 FROM "CandidatoBens" b WHERE b.candidatoId = ca.id);
DROP TABLE tmp_bens26;

